SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON;
IF DB_NAME() NOT LIKE N'TC[_]Vuong[_]Test[_]%' OR OBJECT_ID('dbo.tc_vuong_test_fixture') IS NULL THROW 52790,'Isolated fixture required',1;
BEGIN TRANSACTION;
DECLARE @actor uniqueidentifier=NEWID(),@org uniqueidentifier=NEWID(),@rule uniqueidentifier=NEWID(),@event uniqueidentifier=NEWID(),@second uniqueidentifier=NEWID(),@empty uniqueidentifier=NEWID(),@zero uniqueidentifier=NEWID();
INSERT dbo.tc_users(id,email,user_name,full_name,platform_role) VALUES(@actor,CONCAT(@actor,'@test.invalid'),CONVERT(varchar(36),@actor),'Temporal Admin','ADMIN');
INSERT dbo.tc_organizations(id,name,contact_email) VALUES(@org,'Temporal','temporal@test.invalid');
INSERT dbo.tc_commission_rules(id,organization_id,rate_percent,fixed_fee,effective_from,effective_to) VALUES(@rule,@org,50,0,'2020-01-01','2099-01-01');
INSERT dbo.tc_events(id,organization_id,commission_rule_id,title,end_time) VALUES(@event,@org,@rule,'Temporal','2020-01-01'),(@empty,@org,@rule,'Empty','2020-01-01'),(@zero,@org,@rule,'Zero','2020-01-01');
DECLARE @o1 uniqueidentifier=NEWID(),@o2 uniqueidentifier=NEWID(),@oz uniqueidentifier=NEWID(),@p1 uniqueidentifier=NEWID(),@p2 uniqueidentifier=NEWID(),@r1 uniqueidentifier=NEWID();
INSERT dbo.tc_orders(id,buyer_id,event_id,order_code,status,subtotal_amount,total_amount,paid_at) VALUES(@o1,@actor,@event,CONVERT(varchar(36),@o1),'PAID',100,100,'2026-01-01'),(@o2,@actor,@event,CONVERT(varchar(36),@o2),'PAID',100,100,'2026-01-02'),(@oz,@actor,@zero,CONVERT(varchar(36),@oz),'PAID',0,0,'2026-01-01');
INSERT dbo.tc_payments(id,order_id,amount,status,txn_ref,paid_at) VALUES(@p1,@o1,100,'CAPTURED',CONVERT(varchar(36),@p1),'2026-01-01'),(@p2,@o2,100,'CAPTURED',CONVERT(varchar(36),@p2),'2026-01-02');
UPDATE dbo.tc_orders SET accepted_payment_id=CASE WHEN id=@o1 THEN @p1 ELSE @p2 END WHERE id IN(@o1,@o2);
INSERT dbo.tc_refunds(id,order_id,amount,purpose,status,processed_at) VALUES(@r1,@o1,25,'CUSTOMER_REFUND','COMPLETED','2026-01-03');
INSERT dbo.tc_refund_transfer_logs VALUES(NEWID(),@r1,1,'FAILED','FAILED','2026-01-02',NULL),(NEWID(),@r1,2,'SUCCEEDED','SUCCESS','2026-01-03',NULL);
IF (SELECT gross_revenue FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-02') WHERE event_id=@event)<>100 OR (SELECT total_refund FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-02') WHERE event_id=@event)<>0 THROW 52793,'Cohort must exclude end boundary and later refunds',1;
IF (SELECT total_refund FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-04') WHERE event_id=@event)<>25 OR (SELECT total_commission FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-04') WHERE event_id=@event)<>88 THROW 52793,'Cohort cutoff/fee per order failed',1;
IF (SELECT ticket_captured FROM dbo.fn_GetOrganizationCashFlow(@org,'2026-01-03','2026-01-04') WHERE event_id=@event)<>0 OR (SELECT ticket_refund FROM dbo.fn_GetOrganizationCashFlow(@org,'2026-01-03','2026-01-04') WHERE event_id=@event)<>25 THROW 52793,'Cashflow must include refund of prior cohort',1;
IF (SELECT total_refund FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-03') WHERE event_id=@event)<>0 THROW 52793,'Refund cutoff must exclude exact toUtc',1;
IF EXISTS(SELECT 1 FROM dbo.fn_GetSettlementBlockers(@event,SYSUTCDATETIME()) WHERE blocker_type='REFUND') THROW 52793,'Historical FAILED attempt must not block completed refund',1;
PRINT 'PASS: half-open cohort, historical refund cutoff, per-order rounding, cashflow prior-cohort refund, resolved FAILED history';
EXEC dbo.usp_RecalculateSettlement @empty,@actor,0;
IF EXISTS(SELECT 1 FROM dbo.tc_settlements WHERE event_id=@empty) THROW 52793,'No eligible orders must not create settlement',1;
IF NOT EXISTS(SELECT 1 FROM dbo.vw_EventSalesReport WHERE event_id=@empty AND gross_revenue=0 AND paid_order_count=0) THROW 52793,'Zero event report missing',1;
EXEC dbo.usp_RecalculateSettlement @zero,@actor,0;
DECLARE @zs uniqueidentifier=(SELECT id FROM dbo.tc_settlements WHERE event_id=@zero);
EXEC dbo.usp_ConfirmSettlement @zs,@actor,0;
IF (SELECT status FROM dbo.tc_settlements WHERE id=@zs)<>'PAID' OR EXISTS(SELECT 1 FROM dbo.tc_settlement_transfer_logs WHERE settlement_id=@zs) THROW 52793,'Zero net must be PAID without fake transfer',1;
PRINT 'PASS: empty report/no header; zero-net PAID without transfer';
UPDATE dbo.tc_events SET status='CANCELLED',end_time='2099-01-01' WHERE id=@event;
IF NOT EXISTS(SELECT 1 FROM dbo.fn_GetSettlementBlockers(@event,SYSUTCDATETIME()) WHERE blocker_type='EVENT_NOT_ENDED') OR NOT EXISTS(SELECT 1 FROM dbo.fn_GetSettlementBlockers(@event,SYSUTCDATETIME()) WHERE blocker_type='CANCELLED_REVENUE') THROW 52793,'Cancelled event must await end and refund obligations',1;
UPDATE dbo.tc_events SET end_time='2020-01-01' WHERE id=@event;
DECLARE @r2 uniqueidentifier=NEWID(),@r3 uniqueidentifier=NEWID(),@work uniqueidentifier=NEWID();
INSERT dbo.tc_refunds(id,order_id,amount,purpose,status,processed_at) VALUES(@r2,@o1,75,'CUSTOMER_REFUND','COMPLETED','2026-01-04'),(@r3,@o2,100,'CUSTOMER_REFUND','COMPLETED','2026-01-04');
INSERT dbo.tc_refund_transfer_logs VALUES(NEWID(),@r2,1,'SUCCEEDED','R2','2026-01-04',NULL),(NEWID(),@r3,1,'SUCCEEDED','R3','2026-01-04',NULL);
INSERT dbo.tc_outbox(id,event_type,payload,status) VALUES(@work,'EVENT_CANCELLED',(SELECT @event eventId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),'PENDING');
IF NOT EXISTS(SELECT 1 FROM dbo.fn_GetSettlementBlockers(@event,SYSUTCDATETIME()) WHERE blocker_type='CANCELLATION_WORK') THROW 52793,'Unfinished cancellation work must block',1;
UPDATE dbo.tc_outbox SET status='PUBLISHED' WHERE id=@work;
IF EXISTS(SELECT 1 FROM dbo.fn_GetSettlementBlockers(@event,SYSUTCDATETIME())) THROW 52793,'Completed cancellation remains blocked',1;
EXEC dbo.usp_RecalculateSettlement @event,@actor,0;
DECLARE @s uniqueidentifier=(SELECT id FROM dbo.tc_settlements WHERE event_id=@event);
EXEC dbo.usp_ConfirmSettlement @s,@actor,0;
IF (SELECT total_commission FROM dbo.tc_settlements WHERE id=@s)<>0 OR (SELECT status FROM dbo.tc_settlements WHERE id=@s)<>'PAID' THROW 52793,'Full refund cancellation must have zero fee and payable',1;
PRINT 'PASS: cancelled scheduled-end, uncreated refund obligations, unfinished outbox, completed full-refund confirmation';
ROLLBACK;
GO
